// Shared Scene Container that handles continuous entrance/exit blending
const SceneContainer: React.FC<{
  frame: number;
  start: number;
  end: number;
  fps: number;
  children?: React.ReactNode;
}> = ({ frame, start, end, fps, children }) => {
  if (frame < start - 10 || frame > end + 30) return null;

  const enter = spring({ fps, frame: frame - start, config: { damping: 14 } });
  const exit = spring({ fps, frame: frame - (end - 15), config: { damping: 14 } });

  const opacity = Math.max(0, enter - exit);
  const y = (1 - enter) * 50 - exit * 50;

  return (
    <AbsoluteFill
      style={{
        opacity,
        transform: `translateY(${y}px)`,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {children}
    </AbsoluteFill>
  );
};

